package deposit.service;

import deposit.common.*;
import deposit.repository.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import org.neo4j.graphdb.Node;

/** Expands row inputs into an immutable package graph with owned disk spools. */
final class ImportRowExpansion {
    private final RequestContext c;
    private final CoreRepository repo;
    private final ResourceRepository resources;

    ImportRowExpansion(RequestContext c,CoreRepository repo,ResourceRepository resources){this.c=c;this.repo=repo;this.resources=resources;}

    private Path stagedPath(String relative){try{return resources.files.path(relative);}catch(IOException e){throw new UncheckedIOException(e);}}
    RowSource newRowSource(Path path)throws IOException{return new RowSource(path);}

Iterable<Map<String,Object>> inlineRows(List<?> input){return ()->new Iterator<>(){final Iterator<?> source=input.iterator();public boolean hasNext(){return source.hasNext();}public Map<String,Object> next(){c.state.kernel.assertOpen();Map<String,Object> row=ValueCodec.map(source.next());BaseService.fields(row,"id","values");Map<String,Object> values=ValueCodec.map(row.get("values"));var presence=new LinkedHashMap<String,Object>();values.keySet().forEach(k->presence.put(k,true));return Json.map("rowId",row.get("id"),"values",values,"presence",presence);}};}
static final class RowSource implements Iterable<Map<String,Object>>,AutoCloseable {
    private final Json.ArrayReader reader;
    RowSource(Path path)throws IOException {reader=new Json.ArrayReader(path,"rows");}
    public Iterator<Map<String,Object>> iterator(){return new Iterator<>(){Map<String,Object> next=read();private Map<String,Object> read(){try{return reader.next();}catch(IOException e){throw new UncheckedIOException(e);}}public boolean hasNext(){return next!=null;}public Map<String,Object> next(){if(next==null)throw new NoSuchElementException();Map<String,Object> raw=next;next=read();return Json.map("rowId",raw.get("rowId"),"values",ValueCodec.map(raw.get("values")),"presence",ValueCodec.map(raw.get("presence")));}};}
    public void close()throws IOException{reader.close();}
}
static void writeTabularPackage(Path destination,Map<String,Object> manifest,Map<String,Object> graph){try{Files.createDirectories(destination.getParent());ExchangePackageCodec.write(destination,manifest,graph,null,Map.of());}catch(IOException e){throw new UncheckedIOException(e);}}

static final class TabularExpansion implements AutoCloseable {
    private final Map<String,Object> data;private final List<DiskJsonList> spools;private final ImportScratch indexes;
    TabularExpansion(Map<String,Object> data,List<DiskJsonList> spools,ImportScratch indexes){this.data=data;this.spools=spools;this.indexes=indexes;}
    Map<String,Object> data(){return data;}
    public void close(){for(DiskJsonList spool:spools)try{spool.close();}catch(IOException ignored){}try{indexes.close();}catch(IOException ignored){}}
}
TabularExpansion tabularPackage(Iterable<Map<String,Object>> rows,List<Map<String,Object>> columns,Map<String,Object> rawTargets,List<?> rawRelationships,Map<String,Object> rules)throws IOException{
    var spools=new ArrayList<DiskJsonList>();ImportScratch indexes=new ImportScratch(stagedPath("staging/imports"),()->c.state.kernel.assertOpen());
    try {
    var targets=new LinkedHashMap<String,Map<String,Object>>();var templates=new TreeMap<String,String>();var schemaByClass=new TreeMap<String,TreeMap<String,String>>();var sourceTypes=new HashMap<String,String>();if(columns!=null)for(Map<String,Object> column:columns)sourceTypes.put((String)column.get("name"),ValueCodec.type(column.get("type")));
    for(var entry:rawTargets.entrySet()){
        String column=entry.getKey();Map<String,Object> spec=ValueCodec.map(entry.getValue());BaseService.fields(spec,"object","className","descriptor","type","conversion","srid","verticalSrid");String template=BaseService.string(spec.get("object")),className=BaseService.name(spec.get("className")),descriptor=BaseService.name(spec.get("descriptor"));if(template.isBlank()||template.contains("/")||className.isBlank()||descriptor.isBlank())c.fail("VALIDATION_FAILED","Target template, Class, and Descriptor names must be nonempty; templates cannot contain '/'");
        String oldTemplate=templates.putIfAbsent(template,className);if(oldTemplate!=null&&!oldTemplate.equals(className))c.fail("VALIDATION_FAILED","One Object template cannot map to multiple Classes");Node clazz=repo.find("Class",Map.of("namespaceId",c.namespaceId,"name",className));Node declaration=clazz==null?null:repo.declaration(clazz,descriptor);Object declared=spec.get("type");String type=declared==null?(declaration==null?null:(String)declaration.getProperty("type")):ValueCodec.type(declared);if(type==null)c.fail("VALIDATION_FAILED","A new Descriptor target requires an explicit type");if(declaration!=null&&!type.equals(declaration.getProperty("type")))c.fail("TYPE_CONFLICT","Target type differs from its receiving declaration");
        String key=className+"\u0000"+descriptor;String prior=schemaByClass.computeIfAbsent(className,k->new TreeMap<>()).putIfAbsent(descriptor,type);if(prior!=null&&!prior.equals(type))c.fail("TYPE_CONFLICT","Targets disagree on a Class Descriptor type");String conversion=BaseService.string(spec.getOrDefault("conversion","identity"));if(!Set.of("identity","integerToFloat","floatToIntegerExact").contains(conversion))c.fail("VALIDATION_FAILED","Unsupported tabular conversion");if(conversion.equals("integerToFloat")&&!type.equals("Float")||conversion.equals("floatToIntegerExact")&&!type.equals("Integer"))c.fail("TYPE_CONFLICT","Conversion does not match its target type");spec.put("object",template);spec.put("className",className);spec.put("descriptor",descriptor);spec.put("type",type);spec.put("conversion",conversion);targets.put(column,spec);
    }
    if(columns!=null)for(String name:sourceTypes.keySet())if(!targets.containsKey(name))c.fail("VALIDATION_FAILED","Every staged table column must have an explicit target");
    for(Object raw:rawRelationships){Map<String,Object> edge=ValueCodec.map(raw);BaseService.fields(edge,"source","label","target","weight");String source=BaseService.string(edge.get("source")),target=BaseService.string(edge.get("target")),label=BaseService.name(edge.get("label"));if(!templates.containsKey(source)||!templates.containsKey(target)||label.isBlank())c.fail("VALIDATION_FAILED","Relationship templates and label must be declared by targets");edge.put("label",label);}
    var classIds=new TreeMap<String,String>();var classes=new ArrayList<Map<String,Object>>();for(var classEntry:schemaByClass.entrySet()){String classId=UUID.randomUUID().toString();classIds.put(classEntry.getKey(),classId);var decls=new ArrayList<Map<String,Object>>();for(var decl:classEntry.getValue().entrySet())decls.add(PortableImportRecords.classDescriptor(UUID.randomUUID().toString(),c.namespaceId,classId,decl.getKey(),decl.getValue(),(long)decls.size(),""));classes.add(PortableImportRecords.clazz(classId,c.namespaceId,classEntry.getKey(),decls));}
    Path spoolRoot=stagedPath("staging/imports");var objects=new DiskJsonList(spoolRoot,"objects-");spools.add(objects);var memberships=new DiskJsonList(spoolRoot,"memberships-");spools.add(memberships);var descriptors=new DiskJsonList(spoolRoot,"descriptors-");spools.add(descriptors);var geometries=new DiskJsonList(spoolRoot,"geometries-");spools.add(geometries);var relationships=new DiskJsonList(spoolRoot,"relationships-");spools.add(relationships);Map<String,Object> rowIds=indexes.map(),clearByObject=indexes.map(),blankByObject=indexes.map(),seenRows=indexes.map();
    for(Map<String,Object> row:rows){indexes.check();String rowId=BaseService.string(row.get("rowId"));if(rowId.isBlank()||rowId.contains("/")||seenRows.putIfAbsent(rowId,true)!=null)c.fail("VALIDATION_FAILED","Row IDs must be unique, nonempty, and must not contain '/'");Map<String,Object> values=ValueCodec.map(row.get("values")),presence=ValueCodec.map(row.get("presence"));for(String name:values.keySet())if(!targets.containsKey(name))c.fail("VALIDATION_FAILED","Supplied column has no target: "+name);
    var objectsForRow=new HashMap<String,String>();for(var template:templates.entrySet()){String inputId=UUID.randomUUID().toString(),classId=classIds.get(template.getValue());objectsForRow.put(template.getKey(),inputId);rowIds.put(inputId,rowId+"/"+template.getKey());objects.add(PortableImportRecords.object(inputId,c.namespaceId,classId,List.of(0.0,0.0)));memberships.add(PortableImportRecords.membership(UUID.randomUUID().toString(),c.namespaceId,inputId,classId));}
    var suppliedByTemplate=new HashMap<String,Set<String>>();for(var target:targets.entrySet()){String column=target.getKey();Map<String,Object> spec=target.getValue();String template=(String)spec.get("object"),field=(String)spec.get("descriptor");boolean present=Boolean.TRUE.equals(presence.get(column))&&values.containsKey(column);Object rawValue=values.get(column);if(!present||rawValue==null||rawValue instanceof String s&&s.isEmpty()){String objectId=objectsForRow.get(template);var names=new ArrayList<Object>((List<?>)blankByObject.getOrDefault(objectId,List.of()));if(!names.contains(field))names.add(field);blankByObject.put(objectId,names);continue;}suppliedByTemplate.computeIfAbsent(template,k->new HashSet<>()).add(field);String type=(String)spec.get("type"),conversion=(String)spec.get("conversion");Object value=convertTabularValue(type,conversion,rawValue,sourceTypes.get(column),spec);if("DResource".equals(type))c.fail("VALIDATION_FAILED","Tabular DResource import requires a resolved same-Namespace resource reference");String objectId=objectsForRow.get(template),descriptorId=UUID.randomUUID().toString();var descriptor=PortableImportRecords.descriptor(descriptorId,c.namespaceId,objectId,field,ExchangePackageCodec.encodeValue(type,value));if("DGeometry".equals(type)&&value!=null){String geometryId=UUID.randomUUID().toString();descriptor.put("geometryId",geometryId);Map<String,Object> normalized=ValueCodec.map(value);String geometryType=(String)GeometryCodec.fromWkt(normalized.get("wkt"),normalized.get("srid"),normalized.get("verticalSrid")).get("geometryType");geometries.add(PortableImportRecords.geometry(normalized,geometryId,c.namespaceId,descriptorId,geometryType));}descriptors.add(descriptor);}
        for(Object raw:rawRelationships){Map<String,Object> edge=ValueCodec.map(raw);Map<String,Object> relation=PortableImportRecords.relationship(UUID.randomUUID().toString(),c.namespaceId,objectsForRow.get(edge.get("source")),objectsForRow.get(edge.get("target")),(String)edge.get("label"));if(edge.get("weight") instanceof Number weight)relation.put("weight",weight.doubleValue());relationships.add(relation);}
    }
    var classRelationships=new ArrayList<Map<String,Object>>();var classEdges=new HashSet<String>();for(Object raw:rawRelationships){Map<String,Object> edge=ValueCodec.map(raw);String sourceClass=templates.get(edge.get("source")),targetClass=templates.get(edge.get("target")),label=(String)edge.get("label"),key=sourceClass+"\u0000"+targetClass+"\u0000"+label;if(classEdges.add(key))classRelationships.add(PortableImportRecords.classRelationship(UUID.randomUUID().toString(),c.namespaceId,classIds.get(sourceClass),classIds.get(targetClass),label));}
    var graph=Json.map("classes",classes,"objects",objects,"descriptors",descriptors,"geometries",geometries,"memberships",memberships,"relationships",relationships,"classRelationships",classRelationships,"patterns",List.of(),"userTools",List.of(),"resources",List.of());var manifest=Json.map("packageId",UUID.randomUUID().toString(),"sourceNamespaceId",c.namespaceId,"name","Tabular import","description","","depositVersion",DepositInfo.version(),"historyMode","disabled","exportedRevision",repo.sequence(c.namespaceId),"createdAt",c.timestamp.toString(),"rootIds",List.of(),"scope","namespace","files",Map.of(),"includeHistory",false);return new TabularExpansion(Json.map("manifest",manifest,"graph",graph,"rowIds",rowIds,"clears",clearByObject,"blanks",blankByObject),spools,indexes);
    } catch(RuntimeException|IOException error){for(DiskJsonList spool:spools)try{spool.close();}catch(IOException ignored){}try{indexes.close();}catch(IOException suppressed){error.addSuppressed(suppressed);}throw error;}
}
Object convertTabularValue(String targetType,String conversion,Object raw,String sourceType,Map<String,Object> spec){
    try{Object value=raw;if(conversion.equals("integerToFloat")){if(!"Integer".equals(sourceType)&&sourceType!=null)c.fail("TYPE_CONFLICT","integerToFloat requires an Integer source column");long n=value instanceof Number number?number.longValue():Long.parseLong(value.toString());return (double)n;}
        if(conversion.equals("floatToIntegerExact")){if(!"Float".equals(sourceType)&&sourceType!=null)c.fail("TYPE_CONFLICT","floatToIntegerExact requires a Float source column");double d=value instanceof Number number?number.doubleValue():Double.parseDouble(value.toString());if(!Double.isFinite(d))throw new ArithmeticException();return java.math.BigDecimal.valueOf(d).longValueExact();}
        if(raw instanceof String s&&!"String".equals(targetType)){value=switch(targetType){case "Integer"->Long.parseLong(s);case "Float"->{double d=Double.parseDouble(s);if(!Double.isFinite(d))throw new IllegalArgumentException();yield d;}case "Boolean"->{if(!Set.of("true","false").contains(s))throw new IllegalArgumentException();yield Boolean.valueOf(s);}case "List","DDict"->Json.read(s);case "Point"->{Object srid=spec.get("srid");if(!(srid instanceof Number))throw new IllegalArgumentException("Point mapping requires srid");Map<String,Object> geometry=TabularValueCodec.parseGeometryValue(s,srid,spec.get("verticalSrid"));if(!"Point".equals(geometry.get("geometryType")))throw new IllegalArgumentException("Point value must be a POINT");yield Json.map("srid",((Number)srid).longValue(),"coordinates",geometry.get("coordinates"));}case "DGeometry"->TabularValueCodec.parseGeometryValue(s,spec.get("srid"),spec.get("verticalSrid"));default->s;};}
        if("DGeometry".equals(targetType)&&raw instanceof Map<?,?> geometry&&sourceType!=null&&sourceType.equals("DGeometry")){Map<String,Object> supplied=ValueCodec.map(raw);if(spec.get("srid") instanceof Number n&&!Objects.equals(n.longValue(),supplied.get("srid")))c.fail("VALIDATION_FAILED","Geometry SRID conflicts with mapping");if(spec.get("verticalSrid") instanceof Number n&&!Objects.equals(n.longValue(),supplied.get("verticalSrid")))c.fail("VALIDATION_FAILED","Geometry vertical SRID conflicts with mapping");}
        return ValueCodec.normalize(targetType,value);
    }catch(ExceptionHandler.DepositException e){throw e;}catch(RuntimeException e){c.fail("VALIDATION_FAILED","Row value cannot be converted to "+targetType);return null;}
}

}
